do $$ declare p record; args text; state text; begin
 for p in select f.* from pg_proc f join pg_namespace n on n.oid=f.pronamespace where n.nspname='public' and f.prosecdef and f.prorettype<>'trigger'::regtype and has_function_privilege('authenticated',f.oid,'EXECUTE') and f.proname not in ('get_consent_manifest','get_my_consent_status','complete_signup_consents','record_required_consents','set_optional_consent','current_terms_consent_status','record_terms_consent','email_available') loop
 select string_agg('NULL::'||format_type(a,null),',' order by ord) into args from unnest(p.proargtypes::oid[]) with ordinality v(a,ord);
 state:=pg_temp.sqlstate_of('select public.'||quote_ident(p.proname)||'('||coalesce(args,'')||')');
 if state<>'S1001' then raise exception 'Pending callable gate failed: % / %',p.proname,state; end if;
 end loop;
end; $$;
